from __future__ import absolute_import, division, print_function,\
    unicode_literals
from builtins import object
from abc import ABCMeta, abstractmethod
from future import standard_library
from future.utils import with_metaclass
standard_library.install_aliases()


class ToolBase(with_metaclass(ABCMeta, object)):

    TOOL = None

    @abstractmethod
    def traffic_setup(self):
        pass

    @abstractmethod
    def traffic_start(self, profile):
        pass

    @abstractmethod
    def traffic_stop(self):
        pass

    @abstractmethod
    def traffic_teardown(self):
        pass

    @classmethod
    def check_tool(cls, tool):
        return tool == cls.TOOL
